from lessons_1 import lesson

lesson("dividends", 2, 4, None, [0, 2, 1],
 en=dict(t="What dividends are", s="A dividend is a share of profits that a company may pay to its shareholders — it is never guaranteed.",
  sec=[("How dividends work", "The company's management proposes a dividend and shareholders approve it. To receive it you must own the share before the ex-dividend date. On that date the share price usually drops by roughly the dividend amount, because cash leaves the company. Taxes are often withheld in the company's country."),
       ("What dividends do not mean", "A high dividend yield can be a warning sign: the price may have fallen because investors expect problems, and the dividend may be cut. A company paying more than it earns cannot do so for long. Companies that pay no dividend may reinvest profits instead.")],
  a="A dividend is like an orchard owner handing out some of the harvest: the orchard is worth a little less right after, and a bad year can mean no fruit to share.",
  k=["Dividends are decided by the company and can be cut.", "The price usually falls by about the dividend on the ex-dividend date.", "A very high yield deserves extra scrutiny."],
  q=[("Are dividends guaranteed?", ["No, the company can reduce or stop them", "Yes, by law", "Yes, if the company is large"], "Dividends depend on the company's decisions and finances."),
     ("What usually happens to the share price on the ex-dividend date?", ["It doubles", "It is unaffected", "It drops by about the dividend"], "Cash leaves the company, so its value falls by about that amount."),
     ("Why can a very high dividend yield be a warning sign?", ["High yields are illegal", "The price may have fallen because problems are expected", "It means the company is growing fast"], "Yield = dividend / price; a falling price raises the yield.")]),
 ru=dict(t="Что такое дивиденды", s="Дивиденд — часть прибыли, которую компания может выплатить акционерам; он никогда не гарантирован.",
  sec=[("Как работают дивиденды", "Руководство компании предлагает дивиденд, а акционеры его утверждают. Чтобы получить его, нужно владеть акцией до даты отсечки (экс-дивидендной даты). В этот день цена акции обычно снижается примерно на размер дивиденда, потому что деньги уходят из компании. Налог часто удерживается в стране компании."),
       ("Чего дивиденды не означают", "Высокая дивидендная доходность может быть тревожным сигналом: цена могла упасть, потому что инвесторы ждут проблем, и дивиденд могут сократить. Компания не может долго платить больше, чем зарабатывает. Компании без дивидендов могут вместо этого реинвестировать прибыль.")],
  a="Дивиденд — как раздача части урожая владельцем сада: сразу после этого сад стоит немного меньше, а в неурожайный год делиться может быть нечем.",
  k=["Дивиденды решает компания, и их могут сократить.", "В экс-дивидендную дату цена обычно падает примерно на размер дивиденда.", "Очень высокая доходность требует особой проверки."],
  q=[("Гарантированы ли дивиденды?", ["Нет, компания может уменьшить или прекратить их", "Да, по закону", "Да, если компания крупная"], "Дивиденды зависят от решений и финансов компании."),
     ("Что обычно происходит с ценой акции в экс-дивидендную дату?", ["Удваивается", "Не меняется", "Снижается примерно на размер дивиденда"], "Деньги уходят из компании, и её стоимость снижается примерно на эту сумму."),
     ("Почему очень высокая дивидендная доходность может настораживать?", ["Высокая доходность запрещена", "Цена могла упасть из-за ожидаемых проблем", "Это значит, что компания быстро растёт"], "Доходность = дивиденд / цена; падение цены увеличивает доходность.")]),
 cs=dict(t="Co jsou dividendy", s="Dividenda je podíl na zisku, který firma může vyplatit akcionářům — nikdy není zaručená.",
  sec=[("Jak dividendy fungují", "Vedení firmy navrhne dividendu a akcionáři ji schválí. Abyste ji dostali, musíte akcii vlastnit před rozhodným dnem (ex-dividendovým dnem). V ten den cena akcie obvykle klesne přibližně o výši dividendy, protože z firmy odcházejí peníze. Daň se často sráží v zemi firmy."),
       ("Co dividendy neznamenají", "Vysoký dividendový výnos může být varováním: cena mohla klesnout, protože investoři čekají problémy, a dividenda může být snížena. Firma nemůže dlouho vyplácet víc, než vydělává. Firmy bez dividend mohou zisky místo toho reinvestovat.")],
  a="Dividenda je jako když majitel sadu rozdá část úrody: sad má hned potom o něco menší hodnotu a ve špatném roce nemusí být co rozdávat.",
  k=["O dividendách rozhoduje firma a mohou být sníženy.", "V ex-dividendový den cena obvykle klesne přibližně o dividendu.", "Velmi vysoký výnos si zaslouží zvláštní prověření."],
  q=[("Jsou dividendy zaručené?", ["Ne, firma je může snížit nebo zastavit", "Ano, ze zákona", "Ano, pokud je firma velká"], "Dividendy závisejí na rozhodnutích a financích firmy."),
     ("Co se obvykle stane s cenou akcie v ex-dividendový den?", ["Zdvojnásobí se", "Nezmění se", "Klesne přibližně o dividendu"], "Z firmy odcházejí peníze, takže její hodnota klesne přibližně o tuto částku."),
     ("Proč může být velmi vysoký dividendový výnos varováním?", ["Vysoké výnosy jsou nezákonné", "Cena mohla klesnout kvůli očekávaným problémům", "Znamená, že firma rychle roste"], "Výnos = dividenda / cena; klesající cena výnos zvyšuje.")]))

lesson("coupons", 2, 4, None, [1, 0, 2],
 en=dict(t="What a coupon is", s="A coupon is the interest a bond pays, usually once or twice a year, as a percentage of its face value.",
  sec=[("Coupon, price and yield", "A bond with a face value of 1 000 and a 4 % annual coupon pays 40 a year. If you buy it below face value, your yield to maturity is higher than 4 %; above face value, lower. The coupon is fixed for most bonds, but the price — and therefore the yield for a new buyer — changes every day."),
       ("Accrued interest", "Between coupon dates, interest builds up day by day. When you buy a bond, you usually pay the seller the interest accrued since the last coupon, and you receive the whole next coupon. Quoted bond prices are usually 'clean' (without accrued interest) and in percent of face value.")],
  a="A coupon is like rent paid by a tenant: a fixed amount on fixed dates, as long as the tenant can pay.",
  k=["Coupon = interest in percent of face value.", "Yield depends on the price you pay, not only the coupon.", "Buyers usually pay the seller accrued interest."],
  q=[("A bond with face value 1 000 has a 4 % annual coupon. How much does it pay per year?", ["4", "40", "400"], "4 % of 1 000 is 40."),
     ("If you buy a bond below face value, how does your yield compare to the coupon rate?", ["Higher", "Lower", "Always equal"], "You also gain the difference up to face value at maturity."),
     ("What is accrued interest?", ["A penalty for late payment", "The bond's credit rating", "Interest built up since the last coupon"], "Buyers compensate sellers for the interest earned so far.")]),
 ru=dict(t="Что такое купон", s="Купон — проценты, которые платит облигация, обычно раз или два в год, в процентах от номинала.",
  sec=[("Купон, цена и доходность", "Облигация номиналом 1 000 с годовым купоном 4 % платит 40 в год. Если купить её ниже номинала, доходность к погашению будет выше 4 %, выше номинала — ниже. Купон у большинства облигаций фиксирован, а цена — и значит доходность для нового покупателя — меняется каждый день."),
       ("Накопленный купонный доход", "Между датами выплат проценты накапливаются день за днём. Покупая облигацию, вы обычно платите продавцу НКД с даты прошлого купона, а получаете весь следующий купон. Котировки облигаций обычно «чистые» (без НКД) и в процентах от номинала.")],
  a="Купон похож на арендную плату: фиксированная сумма в фиксированные даты, пока арендатор в состоянии платить.",
  k=["Купон — проценты от номинала.", "Доходность зависит от цены покупки, а не только от купона.", "Покупатель обычно платит продавцу НКД."],
  q=[("Облигация номиналом 1 000 имеет годовой купон 4 %. Сколько она платит в год?", ["4", "40", "400"], "4 % от 1 000 — это 40."),
     ("Если купить облигацию ниже номинала, как доходность соотносится со ставкой купона?", ["Выше", "Ниже", "Всегда равна"], "Вы ещё получаете разницу до номинала при погашении."),
     ("Что такое НКД?", ["Штраф за просрочку", "Кредитный рейтинг облигации", "Проценты, накопленные с даты прошлого купона"], "Покупатель компенсирует продавцу уже заработанные проценты.")]),
 cs=dict(t="Co je kupon", s="Kupon je úrok, který dluhopis vyplácí, obvykle jednou nebo dvakrát ročně, v procentech jmenovité hodnoty.",
  sec=[("Kupon, cena a výnos", "Dluhopis s jmenovitou hodnotou 1 000 a ročním kuponem 4 % vyplácí 40 ročně. Když ho koupíte pod jmenovitou hodnotou, je váš výnos do splatnosti vyšší než 4 %; nad ní nižší. Kupon je u většiny dluhopisů pevný, ale cena — a tím i výnos pro nového kupujícího — se mění každý den."),
       ("Alikvótní úrokový výnos", "Mezi výplatami kuponu se úrok načítá den po dni. Při koupi dluhopisu obvykle zaplatíte prodávajícímu úrok naběhlý od posledního kuponu a dostanete celý příští kupon. Ceny dluhopisů se obvykle uvádějí „čisté“ (bez AÚV) a v procentech jmenovité hodnoty.")],
  a="Kupon je jako nájem placený nájemníkem: pevná částka v pevné dny, dokud má nájemník z čeho platit.",
  k=["Kupon = úrok v procentech jmenovité hodnoty.", "Výnos závisí na ceně, kterou zaplatíte, ne jen na kuponu.", "Kupující obvykle platí prodávajícímu alikvótní úrok."],
  q=[("Dluhopis s jmenovitou hodnotou 1 000 má roční kupon 4 %. Kolik vyplatí za rok?", ["4", "40", "400"], "4 % z 1 000 je 40."),
     ("Když dluhopis koupíte pod jmenovitou hodnotou, jak je výnos oproti kupónové sazbě?", ["Vyšší", "Nižší", "Vždy stejný"], "Při splatnosti navíc získáte rozdíl do jmenovité hodnoty."),
     ("Co je alikvótní úrokový výnos?", ["Pokuta za pozdní platbu", "Rating dluhopisu", "Úrok naběhlý od posledního kuponu"], "Kupující kompenzuje prodávajícímu dosud naběhlý úrok.")]))

lesson("compound-interest", 3, 5, "compoundInterest", [2, 0, 1],
 en=dict(t="What compound interest is", s="Compounding means earning returns on earlier returns, so growth accelerates over long periods.",
  sec=[("Returns on returns", "If 1 000 earns 5 % in a year, you have 1 050. In the second year, 5 % is earned on 1 050, giving 1 102.50 — the extra 2.50 is interest on interest. Over decades this effect becomes large: at a constant 5 %, money roughly doubles in about 14 years."),
       ("Time matters, and so do costs", "Compounding rewards starting early and leaving money invested. It works against you too: fees and inflation compound as well, and debt with high interest compounds quickly. Real investments do not grow at a constant rate; the calculator shows the arithmetic, not a forecast.")],
  a="Compounding is like a snowball rolling downhill: the bigger it gets, the more snow it picks up with each turn.",
  k=["Compounding means earning on earlier earnings.", "Time is the most powerful factor.", "Costs, inflation and debt interest compound too."],
  q=[("1 000 grows 10 % a year for two years. What is the result?", ["1 200", "1 100", "1 210"], "1 000 × 1.1 × 1.1 = 1 210; the extra 10 is interest on interest."),
     ("Which factor makes compounding most powerful?", ["A long time horizon", "Checking prices daily", "Frequent trading"], "The longer money compounds, the larger the effect."),
     ("Does compounding also apply to costs?", ["No, only to returns", "Yes, fees and debt interest compound too", "Only for bonds"], "A yearly fee reduces the base on which all later returns are earned.")]),
 ru=dict(t="Что такое сложный процент", s="Сложный процент — это доход на ранее полученный доход, поэтому на длинных сроках рост ускоряется.",
  sec=[("Доход на доход", "Если 1 000 приносит 5 % за год, получается 1 050. Во второй год 5 % начисляются уже на 1 050 — выходит 1 102,50; лишние 2,50 — это проценты на проценты. За десятилетия эффект становится большим: при постоянных 5 % деньги удваиваются примерно за 14 лет."),
       ("Важны время и расходы", "Сложный процент вознаграждает тех, кто начинает рано и не забирает деньги. Но он работает и против вас: комиссии и инфляция тоже накапливаются, а дорогой долг растёт быстро. Реальные вложения не растут с постоянной скоростью; калькулятор показывает арифметику, а не прогноз.")],
  a="Сложный процент — как снежный ком, катящийся с горы: чем он больше, тем больше снега налипает с каждым оборотом.",
  k=["Сложный процент — доход на ранее полученный доход.", "Самый сильный фактор — время.", "Комиссии, инфляция и проценты по долгам тоже накапливаются."],
  q=[("1 000 растёт на 10 % в год два года. Каков результат?", ["1 200", "1 100", "1 210"], "1 000 × 1,1 × 1,1 = 1 210; лишние 10 — проценты на проценты."),
     ("Что делает сложный процент самым сильным?", ["Длинный горизонт", "Ежедневная проверка цен", "Частые сделки"], "Чем дольше деньги работают, тем сильнее эффект."),
     ("Действует ли сложный процент на расходы?", ["Нет, только на доход", "Да, комиссии и проценты по долгам тоже накапливаются", "Только для облигаций"], "Ежегодная комиссия уменьшает базу, на которую начисляется весь будущий доход.")]),
 cs=dict(t="Co je složené úročení", s="Složené úročení znamená výnos z dřívějších výnosů, takže v dlouhém období růst zrychluje.",
  sec=[("Výnosy z výnosů", "Když 1 000 vynese za rok 5 %, máte 1 050. Ve druhém roce se 5 % počítá z 1 050, takže máte 1 102,50 — oněch 2,50 navíc je úrok z úroku. Za desetiletí je efekt velký: při stálých 5 % se peníze zdvojnásobí přibližně za 14 let."),
       ("Záleží na čase i nákladech", "Složené úročení odměňuje brzký začátek a ponechání peněz investovaných. Funguje i proti vám: poplatky a inflace se také skládají a drahý dluh roste rychle. Skutečné investice nerostou stálým tempem; kalkulačka ukazuje aritmetiku, ne prognózu.")],
  a="Složené úročení je jako sněhová koule kutálející se z kopce: čím je větší, tím víc sněhu nabalí při každé otáčce.",
  k=["Složené úročení znamená výnos z dřívějších výnosů.", "Nejsilnějším faktorem je čas.", "Poplatky, inflace a úroky z dluhů se také skládají."],
  q=[("1 000 roste dva roky o 10 % ročně. Jaký je výsledek?", ["1 200", "1 100", "1 210"], "1 000 × 1,1 × 1,1 = 1 210; oněch 10 navíc je úrok z úroku."),
     ("Co dělá složené úročení nejsilnějším?", ["Dlouhý časový horizont", "Denní kontrola cen", "Časté obchodování"], "Čím déle se peníze úročí, tím větší je efekt."),
     ("Platí složené úročení i pro náklady?", ["Ne, jen pro výnosy", "Ano, poplatky a úroky z dluhů se také skládají", "Jen u dluhopisů"], "Roční poplatek zmenšuje základ, ze kterého se počítají všechny další výnosy.")]))

lesson("inflation", 3, 4, "inflation", [0, 1, 1],
 en=dict(t="What inflation is", s="Inflation is the general rise in prices; it reduces what a fixed amount of money can buy.",
  sec=[("Purchasing power", "If inflation is 3 % a year, something costing 100 today costs about 103 next year. Money kept in cash earning less than inflation loses real value. Over 20 years at 3 %, the purchasing power of 100 shrinks to about 55."),
       ("Nominal and real returns", "A nominal return is the change in money terms; a real return subtracts inflation. A savings account paying 2 % while inflation is 4 % has a real return of about −2 %. Central banks such as the Czech National Bank and the European Central Bank aim for inflation of around 2 % and use interest rates to influence it.")],
  a="Inflation is like a slow leak in a tyre: you hardly notice it day to day, but over a long journey it matters a lot.",
  k=["Inflation reduces the purchasing power of money.", "Real return ≈ nominal return − inflation.", "Cash and fixed payments are most exposed."],
  q=[("Savings earn 2 % while inflation is 4 %. What is the approximate real return?", ["−2 %", "6 %", "2 %"], "Real ≈ 2 % − 4 % = −2 %: you can buy less than before."),
     ("Who is most exposed to inflation?", ["Owners of companies that can raise prices", "Holders of a fixed income", "Nobody"], "Fixed payments lose purchasing power when prices rise."),
     ("What do central banks usually use to influence inflation?", ["Share buybacks", "Interest rates", "Exchange opening hours"], "Higher rates tend to slow borrowing and spending.")]),
 ru=dict(t="Что такое инфляция", s="Инфляция — общий рост цен; она уменьшает, сколько можно купить на фиксированную сумму денег.",
  sec=[("Покупательная способность", "При инфляции 3 % в год вещь, стоящая сегодня 100, через год стоит около 103. Деньги на счёте с доходностью ниже инфляции теряют реальную стоимость. За 20 лет при 3 % покупательная способность 100 снижается примерно до 55."),
       ("Номинальная и реальная доходность", "Номинальная доходность — изменение в деньгах, реальная — за вычетом инфляции. Вклад под 2 % при инфляции 4 % даёт реальную доходность около −2 %. Центральные банки, например Чешский национальный банк и Европейский центральный банк, стремятся к инфляции около 2 % и влияют на неё процентными ставками.")],
  a="Инфляция — как медленный прокол шины: день за днём почти незаметно, но на длинной дороге очень важно.",
  k=["Инфляция снижает покупательную способность денег.", "Реальная доходность ≈ номинальная − инфляция.", "Сильнее всего страдают наличные и фиксированные выплаты."],
  q=[("Сбережения приносят 2 %, инфляция 4 %. Какова примерно реальная доходность?", ["−2 %", "6 %", "2 %"], "Реальная ≈ 2 % − 4 % = −2 %: купить можно меньше, чем раньше."),
     ("Кто сильнее всего подвержен инфляции?", ["Владельцы компаний, способных поднимать цены", "Получатели фиксированного дохода", "Никто"], "Фиксированные выплаты теряют покупательную способность при росте цен."),
     ("Чем центральные банки обычно влияют на инфляцию?", ["Обратным выкупом акций", "Процентными ставками", "Часами работы биржи"], "Высокие ставки обычно замедляют кредитование и расходы.")]),
 cs=dict(t="Co je inflace", s="Inflace je celkový růst cen; snižuje, co lze koupit za pevnou částku peněz.",
  sec=[("Kupní síla", "Při inflaci 3 % ročně věc, která dnes stojí 100, bude za rok stát asi 103. Peníze v hotovosti s výnosem nižším než inflace ztrácejí reálnou hodnotu. Za 20 let při 3 % klesne kupní síla 100 přibližně na 55."),
       ("Nominální a reálný výnos", "Nominální výnos je změna v penězích; reálný výnos odečítá inflaci. Spořicí účet s 2 % při inflaci 4 % má reálný výnos asi −2 %. Centrální banky, například Česká národní banka a Evropská centrální banka, cílují inflaci kolem 2 % a ovlivňují ji úrokovými sazbami.")],
  a="Inflace je jako pomalu ucházející pneumatika: den po dni si toho skoro nevšimnete, ale na dlouhé cestě na tom hodně záleží.",
  k=["Inflace snižuje kupní sílu peněz.", "Reálný výnos ≈ nominální výnos − inflace.", "Nejvíce jsou ohroženy hotovost a pevné platby."],
  q=[("Úspory vynášejí 2 %, inflace je 4 %. Jaký je přibližně reálný výnos?", ["−2 %", "6 %", "2 %"], "Reálný ≈ 2 % − 4 % = −2 %: koupíte méně než dřív."),
     ("Kdo je inflaci vystaven nejvíc?", ["Vlastníci firem, které mohou zvyšovat ceny", "Příjemci pevného příjmu", "Nikdo"], "Pevné platby ztrácejí kupní sílu, když ceny rostou."),
     ("Čím centrální banky obvykle ovlivňují inflaci?", ["Zpětným odkupem akcií", "Úrokovými sazbami", "Otevírací dobou burzy"], "Vyšší sazby obvykle zpomalují úvěry a výdaje.")]))
